import { MaterializedView } from "@514labs/moose-lib";

export interface TopProducts {
  product_id: string;
  product_views: number;
  product_carts: number;
  product_purchases: number;
  total_revenue: number;
}

export const TopProductsView = new MaterializedView<TopProducts>("TopProducts", `
  CREATE MATERIALIZED VIEW IF NOT EXISTS TopProducts
  ENGINE = SummingMergeTree()
  ORDER BY product_id
  POPULATE
  AS
  SELECT
    product_id,
    countIf(event_type = 'view') as product_views,
    countIf(event_type = 'cart') as product_carts,
    countIf(event_type = = 'purchase') as product_purchases,
    sumIf(toFloat64OrDefault(properties.price, 0), event_type = 'purchase') as total_revenue
  FROM currentDatabase().ProductEvent
  GROUP BY product_id
`);

