import { MaterializedView } from "@514labs/moose-lib";

export interface ConversionFunnel {
  funnel_step: string;
  unique_users: number;
  total_events: number;
}

export const ConversionFunnelView = new MaterializedView<ConversionFunnel>("ConversionFunnel", `
  CREATE MATERIALIZED VIEW IF NOT EXISTS ConversionFunnel
  ENGINE = SummingMergeTree()
  ORDER BY funnel_step
  POPULATE
  AS
  SELECT
    event_type as funnel_step,
    uniq(user_id) as unique_users,
    count(*) as total_events
  FROM currentDatabase().ProductEvent
  WHERE event_type IN ('view', 'cart', 'purchase')
  GROUP BY event_type
`);

