import { Api } from "@514labs/moose-lib";

// Define query parameters
export interface HourlyActivityParams {
  startDate?: string; // Format: YYYY-MM-DD HH:mm:ss
  endDate?: string;   // Format: YYYY-MM-DD HH:mm:ss
  eventType?: string; // Filter by specific event type
}

// Define response interface
export interface HourlyActivityResponse {
  event_hour: string;
  event_type: string;
  event_count: number;
}

// Create the API endpoint
export const hourlyActivityApi = new Api<HourlyActivityParams, HourlyActivityResponse[]>(
  "hourly-activity",
  async ({ startDate, endDate, eventType }, { client, sql }) => {
    // Build the WHERE clause conditionally
    let whereClause = '';
    const conditions = [];

    if (startDate) {
      conditions.push(`event_hour >= toDateTime('${startDate}')`);
    }
    if (endDate) {
      conditions.push(`event_hour <= toDateTime('${endDate}')`);
    }
    if (eventType) {
      conditions.push(`event_type = '${eventType}'`);
    }

    if (conditions.length > 0) {
      whereClause = `WHERE ${conditions.join(' AND ')}`;
    }

    const result = await client.query.execute<HourlyActivityResponse>(sql`
      SELECT
        toString(event_hour) as event_hour,
        event_type,
        sum(event_count) as event_count
      FROM currentDatabase().HourlyActivity
      ${sql.raw(whereClause)}
      GROUP BY event_hour, event_type
      ORDER BY event_hour DESC, event_type
    `);

    return result.json();
  }
);

