import { IngestPipeline } from "@514labs/moose-lib";

export interface ProductEvent {
  event_id: string;
  event_ts: Date;
  user_id: string;
  product_id: string;
  event_type: "view" | "cart" | "purchase";
  properties: {
    page?: string;
    price?: number;
  };
}

// Create the ingest pipeline with proper ordering for ClickHouse performance
// Order by user_id first (for user-based queries), then event_ts (for time-series analysis)
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: { orderByFields: ["user_id", "event_ts"] },
  stream: true,
  ingestApi: true,
});

