import { ProductEventPipeline } from "../ingest/ProductEvent";

export interface TopProducts {
  product_id: string;
  product_views: number;
  product_carts: number;
  product_purchases: number;
  total_revenue: number;
}

export const TopProductsView = new MaterializedView<TopProducts>({
  selectStatement: sql.statement`
    SELECT
      product_id,
      countIf(event_type = 'view') as product_views,
      countIf(event_type = 'cart') as product_carts,
      countIf(event_type = 'purchase') as product_purchases,
      sumIf(toFloat64OrDefault(properties.price, 0), event_type = 'purchase') as total_revenue
    FROM ${ProductEventPipeline.table}
    GROUP BY product_id
  `,
  selectTables: [ProductEventPipeline.table],
  targetTable: {
    name: "TopProducts",
    engine: ClickHouseEngines.SummingMergeTree,
    orderByFields: ["product_id"],
  },
  materializedViewName: "mv_TopProducts",
});

