import { Api } from "@514labs/moose-lib";

// Define query parameters (empty for this basic funnel, but could add filters like date range)
export interface ConversionFunnelParams {
  // No parameters needed for basic funnel view
}

// Define response interface
export interface ConversionFunnelResponse {
  funnel_step: string;
  unique_users: number;
  total_events: number;
  conversion_rate?: number; // calculated field
}

// Create the API endpoint
export const conversionFunnelApi = new Api<ConversionFunnelParams, ConversionFunnelResponse[]>(
  "conversion-funnel",
  async (params, { client, sql }) => {
    const result = await client.query.execute<{
      funnel_step: string;
      unique_users: number;
      total_events: number;
    }>(sql`
      SELECT
        funnel_step,
        sum(unique_users) as unique_users,
        sum(total_events) as total_events
      FROM currentDatabase().ConversionFunnel
      GROUP BY funnel_step
      ORDER BY
        CASE
          WHEN funnel_step = 'view' THEN 1
          WHEN funnel_step = 'cart' THEN 2
          WHEN funnel_step = 'purchase' THEN 3
          ELSE 4
        END
    `);

    const data = await result.json();

    // Calculate conversion rates (percentage of users who moved to next step)
    const enrichedData: ConversionFunnelResponse[] = data.map((step, index) => {
      let conversion_rate: number | null = null;
      if (index > 0) {
        // Calculate conversion rate from previous step
        const previousStep = data[index - 1];
        conversion_rate = previousStep.unique_users > 0
          ? (step.unique_users / previousStep.unique_users) * 100
          : 0;
      }
      return {
        ...step,
        conversion_rate
      };
    });

    return enrichedData;
  }
);

