#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const INGEST_URL = 'http://localhost:4000/ingest/ProductEvent';
const DATA_DIR = '/data/events';

// Function to load all event files
function loadEventFiles() {
  const files = fs.readdirSync(DATA_DIR)
    .filter(file => file.endsWith('.json'))
    .sort();

  const events = [];
  for (const file of files) {
    const filePath = path.join(DATA_DIR, file);
    const content = fs.readFileSync(filePath, 'utf8');
    const event = JSON.parse(content.trim());
    events.push(event);
  }

  return events;
}

// Function to send a single event to the ingest endpoint
async function sendEvent(event) {
  try {
    const response = await fetch(INGEST_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(event)
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    return { success: true, event_id: event.event_id };
  } catch (error) {
    return { success: false, event_id: event.event_id, error: error.message };
  }
}

// Main function
async function main() {
  console.log('🚀 Loading seed data for analytics pipeline...');

  // Load all events
  console.log('📁 Reading event files from', DATA_DIR);
  const events = loadEventFiles();
  console.log(`✅ Loaded ${events.length} events`);

  // Display sample event
  console.log('📝 Sample event:');
  console.log(JSON.stringify(events[0], null, 2));

  // Test connection to ingest endpoint
  console.log('🔗 Testing connection to ingest endpoint...');
  try {
    const response = await fetch(INGEST_URL.replace('/ProductEvent', '/health'), {
      method: 'GET',
    });
    console.log(`🏥 Health check: ${response.status}`);
  } catch (error) {
    console.log('⚠️  Ingest endpoint not available:', error.message);
    console.log('💡 Make sure to run "moose dev" first');
    process.exit(1);
  }

  // Send all events
  console.log('📤 Sending events to ingest endpoint...');
  const results = [];

  for (let i = 0; i < events.length; i++) {
    const event = events[i];
    console.log(`📦 Sending event ${i + 1}/${events.length}: ${event.event_id}`);

    const result = await sendEvent(event);
    results.push(result);

    if (result.success) {
      console.log(`✅ ${event.event_id} sent successfully`);
    } else {
      console.log(`❌ ${event.event_id} failed: ${result.error}`);
    }

    // Small delay to avoid overwhelming the endpoint
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  // Summary
  const successful = results.filter(r => r.success).length;
  const failed = results.length - successful;

  console.log('\n📊 Results Summary:');
  console.log(`✅ Successful: ${successful}`);
  console.log(`❌ Failed: ${failed}`);
  console.log(`📈 Success rate: ${((successful / results.length) * 100).toFixed(1)}%`);

  if (failed > 0) {
    console.log('\n❌ Failed events:');
    results.filter(r => !r.success).forEach(r => {
      console.log(`- ${r.event_id}: ${r.error}`);
    });
  }

  console.log('\n🎉 Seed data loading complete!');
}

// Run the script
if (require.main === module) {
  main().catch(console.error);
}

module.exports = { loadEventFiles, sendEvent };

