#!/usr/bin/env node

// Configuration
const API_BASE_URL = 'http://localhost:4000/api';

// Test configuration
const TEST_CONFIG = {
  timeout: 200, // 200ms requirement
  retries: 3,
};

// API endpoints to test
const API_ENDPOINTS = [
  {
    name: 'Top Products',
    url: `${API_BASE_URL}/top-products`,
    params: { limit: 5 },
    description: 'Returns top products by revenue and purchases'
  },
  {
    name: 'Conversion Funnel',
    url: `${API_BASE_URL}/conversion-funnel`,
    params: {},
    description: 'Returns conversion funnel metrics (view → cart → purchase)'
  },
  {
    name: 'Hourly Activity',
    url: `${API_BASE_URL}/hourly-activity`,
    params: { eventType: 'purchase' },
    description: 'Returns hourly activity breakdown'
  }
];

// Function to test a single API endpoint
async function testEndpoint(endpoint) {
  const { name, url, params, description } = endpoint;

  // Build URL with query parameters
  const queryParams = new URLSearchParams(params);
  const fullUrl = `${url}?${queryParams}`;

  console.log(`\n🧪 Testing ${name}`);
  console.log(`📝 Description: ${description}`);
  console.log(`🔗 URL: ${fullUrl}`);

  for (let attempt = 1; attempt <= TEST_CONFIG.retries; attempt++) {
    try {
      const startTime = Date.now();

      const response = await Promise.race([
        fetch(fullUrl),
        new Promise((_, reject) =>
          setTimeout(() => reject(new Error('Timeout')), TEST_CONFIG.timeout)
        )
      ]);

      const duration = Date.now() - startTime;

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      console.log(`✅ Success! Response time: ${duration}ms`);
      console.log(`📊 Data preview:`, JSON.stringify(data.slice ? data.slice(0, 3) : data, null, 2));

      return {
        name,
        success: true,
        duration,
        dataLength: Array.isArray(data) ? data.length : 1,
        attempt
      };

    } catch (error) {
      const duration = Date.now() - startTime;
      console.log(`❌ Attempt ${attempt} failed: ${error.message} (${duration}ms)`);

      if (attempt === TEST_CONFIG.retries) {
        return {
          name,
          success: false,
          error: error.message,
          duration,
          attempt
        };
      }

      // Wait before retry
      await new Promise(resolve => setTimeout(resolve, 1000));
    }
  }
}

// Function to test all API endpoints
async function testAllApis() {
  console.log('🚀 Analytics Pipeline API Performance Test');
  console.log(`⏱️  Response time requirement: < ${TEST_CONFIG.timeout}ms`);
  console.log(`🔄 Retries per endpoint: ${TEST_CONFIG.retries}`);

  const results = [];

  for (const endpoint of API_ENDPOINTS) {
    const result = await testEndpoint(endpoint);
    results.push(result);
  }

  // Summary
  console.log('\n📊 Test Results Summary');
  console.log('─'.repeat(50));

  const successful = results.filter(r => r.success);
  const failed = results.filter(r => !r.success);

  successful.forEach(result => {
    console.log(`✅ ${result.name}: ${result.duration}ms (${result.dataLength} records)`);
  });

  failed.forEach(result => {
    console.log(`❌ ${result.name}: ${result.error}`);
  });

  console.log('─'.repeat(50));
  console.log(`📈 Success rate: ${successful.length}/${results.length} (${((successful.length / results.length) * 100).toFixed(1)}%)`);

  if (successful.length > 0) {
    const avgResponseTime = successful.reduce((sum, r) => sum + r.duration, 0) / successful.length;
    console.log(`⏱️  Average response time: ${avgResponseTime.toFixed(1)}ms`);
    console.log(`🎯 Under 200ms: ${successful.every(r => r.duration < TEST_CONFIG.timeout) ? 'YES' : 'NO'}`);
  }

  return {
    total: results.length,
    successful: successful.length,
    failed: failed.length,
    allUnder200ms: successful.every(r => r.duration < TEST_CONFIG.timeout)
  };
}

// Health check function
async function healthCheck() {
  console.log('🏥 Performing health check...');

  try {
    const response = await fetch(`${API_BASE_URL.replace('/api', '')}/health`);
    console.log(`✅ Health check: ${response.status}`);
    return true;
  } catch (error) {
    console.log('❌ Health check failed:', error.message);
    console.log('💡 Make sure the Moose dev server is running with "moose dev"');
    return false;
  }
}

// Main function
async function main() {
  const isHealthy = await healthCheck();

  if (!isHealthy) {
    console.log('\n⚠️  Cannot proceed with API tests - server not available');
    process.exit(1);
  }

  const results = await testAllApis();

  if (results.allUnder200ms && results.failed === 0) {
    console.log('\n🎉 All API endpoints are working and responding under 200ms!');
    process.exit(0);
  } else {
    console.log('\n⚠️  Some tests failed or exceeded response time requirement');
    process.exit(1);
  }
}

// Run the script
if (require.main === module) {
  main().catch(console.error);
}

module.exports = { testEndpoint, testAllApis, healthCheck };

